# ============================================================#  STARFIELD – GAMES EDITION TURBO LAUNCHER + MEMORY GUARDIAN#  Author: Copilot (Games Edition)#  Purpose: Repair, cleanup, optimization, memory protection,#           logging, and high-priority launch for Starfield.exe# ============================================================$log = "$PSScriptRoot\Starfield_TurboLog.txt""=== TURBO LAUNCH + MEMORY GUARDIAN STARTED: $(Get-Date) ===" | Out-File $log -AppendWrite-Host "=== STARFIELD TURBO LAUNCHER – GAMES EDITION (MEMORY GUARDIAN) ===" -ForegroundColor Cyan# -------------------------------# 0. Memory Guardian – Functions# -------------------------------function Get-VRAMGB {    try {        $gpu = Get-CimInstance Win32_VideoController | Select-Object -First 1        return [math]::Round(($gpu.AdapterRAM / 1GB), 2)    }    catch { return 0 }}function Get-StandbyGB {    try {        $mem = Get-Counter '\Memory\Standby Cache Reserve Bytes'        return [math]::Round(($mem.CounterSamples.CookedValue / 1GB), 2)    }    catch { return 0 }}function Get-CommitPct {    try {        $commit = Get-Counter '\Memory\Committed Bytes'        $limit  = Get-Counter '\Memory\Commit Limit'        $pct = ($commit.CounterSamples.CookedValue / $limit.CounterSamples.CookedValue) * 100        return [math]::Round($pct, 2)    }    catch { return 0 }}function Invoke-StandbyFlush {    $esl = "$PSScriptRoot\EmptyStandbyList.exe"    if (Test-Path $esl) {        & $esl standbylist        & $esl modifiedpagelist        "Memory Guardian: Standby/modified page lists flushed." | Out-File $log -Append        Write-Host "[Memory Guardian] Standby list flushed." -ForegroundColor Yellow    }    else {        "Memory Guardian: EmptyStandbyList.exe not found – cannot auto-flush standby." | Out-File $log -Append    }}function Invoke-JunkKill {    $junk = @(        "steamwebhelper",        "EpicWebHelper",        "OneDrive",        "ioloServiceManager",        "ioloTray",        "RadeonSoftware",        "NVIDIA Share",        "NVIDIA Web Helper"    )    foreach ($p in $junk) {        Get-Process $p -ErrorAction SilentlyContinue | Stop-Process -Force -ErrorAction SilentlyContinue    }    "Memory Guardian: Background junk trimmed for RAM headroom." | Out-File $log -Append    Write-Host "[Memory Guardian] Background junk trimmed." -ForegroundColor Yellow}# -------------------------------# 0.1 Memory Guardian – Monitor Loop# -------------------------------$global:MG_LastSample = $nullfunction Start-MemoryGuardian {    param(        [System.Diagnostics.Process] $StarfieldProc    )    $mgLog = "$PSScriptRoot\Starfield_MemoryGuardianLog_$(Get-Date -Format 'yyyy-MM-dd_HH-mm-ss').txt"    "=== MEMORY GUARDIAN STARTED: $(Get-Date) ===" | Out-File $mgLog -Append    "Logging to: $mgLog" | Out-File $log -Append    Write-Host "[Memory Guardian] Monitoring Starfield.exe memory usage..." -ForegroundColor Cyan    while ($StarfieldProc -and -not $StarfieldProc.HasExited) {        try {            $ramGB   = [math]::Round(($StarfieldProc.WorkingSet64 / 1GB), 2)            $privGB  = [math]::Round(($StarfieldProc.PrivateMemorySize64 / 1GB), 2)        }        catch {            break        }        $vramGB   = Get-VRAMGB        $standby  = Get-StandbyGB        $commit   = Get-CommitPct        $sample = [PSCustomObject]@{            Time     = Get-Date            RAM_GB   = $ramGB            Private_GB = $privGB            VRAM_GB  = $vramGB            Standby_GB = $standby            Commit_Pct = $commit        }        $global:MG_LastSample = $sample        $line = "{0:HH:mm:ss} | RAM={1}GB | Private={2}GB | VRAM={3}GB | Standby={4}GB | Commit={5}%" -f `            $sample.Time, $sample.RAM_GB, $sample.Private_GB, $sample.VRAM_GB, $sample.Standby_GB, $sample.Commit_Pct        $line | Out-File $mgLog -Append        # --- Active protections / warnings ---        if ($sample.Commit_Pct -ge 95) {            "WARNING: Commit charge critical (>95%)." | Out-File $mgLog -Append            Write-Host "[Memory Guardian] Commit charge CRITICAL – flushing standby + trimming junk..." -ForegroundColor Red            Invoke-StandbyFlush            Invoke-JunkKill        }        elseif ($sample.Commit_Pct -ge 90) {            "WARNING: Commit charge high (>90%)." | Out-File $mgLog -Append            Write-Host "[Memory Guardian] Commit charge high – consider lowering texture mods / increasing pagefile." -ForegroundColor Yellow        }        if ($sample.RAM_GB -ge 22) {            "WARNING: RAM usage near physical limit." | Out-File $mgLog -Append            Write-Host "[Memory Guardian] RAM near limit – large texture/ENB/mod packs likely." -ForegroundColor Yellow        }        if ($sample.Private_GB -ge 20) {            "WARNING: Private bytes very high – possible memory leak from mods." | Out-File $mgLog -Append        }        if ($sample.Standby_GB -ge 10) {            "WARNING: Standby list pressure high." | Out-File $mgLog -Append            Invoke-StandbyFlush        }        Start-Sleep -Seconds 1    }    "=== MEMORY GUARDIAN STOPPED: $(Get-Date) ===" | Out-File $mgLog -Append    "Memory Guardian log: $mgLog" | Out-File $log -Append}function Analyze-MemoryCrash {    if (-not $global:MG_LastSample) {        "Memory Guardian: No memory samples recorded – cannot analyze." | Out-File $log -Append        return    }    $s = $global:MG_LastSample    "=== MEMORY GUARDIAN – CRASH ANALYSIS ===" | Out-File $log -Append    "Last Sample: $( $s.Time )" | Out-File $log -Append    "RAM: $($s.RAM_GB) GB | Private: $($s.Private_GB) GB | VRAM: $($s.VRAM_GB) GB | Standby: $($s.Standby_GB) GB | Commit: $($s.Commit_Pct)%" | Out-File $log -Append    Write-Host "`n[Memory Guardian] Crash Analysis:" -ForegroundColor Cyan    Write-Host "  RAM: $($s.RAM_GB) GB | Private: $($s.Private_GB) GB | VRAM: $($s.VRAM_GB) GB | Standby: $($s.Standby_GB) GB | Commit: $($s.Commit_Pct)%" -ForegroundColor Yellow    if ($s.Commit_Pct -ge 95) {        Write-Host "  → Likely cause: SYSTEM COMMIT EXHAUSTION (pagefile too small or overall memory pressure)." -ForegroundColor Red        Write-Host "    Fix:" -ForegroundColor Green        Write-Host "      - Increase Windows pagefile (System Managed or at least 1.5–2x RAM)." -ForegroundColor Green        Write-Host "      - Close browsers/launchers/other games while playing." -ForegroundColor Green        Write-Host "      - Reduce heavy texture/4K mods." -ForegroundColor Green    }    elseif ($s.RAM_GB -ge 22 -or $s.Private_GB -ge 20) {        Write-Host "  → Likely cause: PHYSICAL RAM EXHAUSTION / MOD MEMORY LEAK." -ForegroundColor Red        Write-Host "    Fix:" -ForegroundColor Green        Write-Host "      - Disable or reduce large texture packs / heavy script mods." -ForegroundColor Green        Write-Host "      - Lower in-game texture/LOD settings." -ForegroundColor Green        Write-Host "      - Keep browser/Discord/other apps closed." -ForegroundColor Green    }    elseif ($s.Standby_GB -ge 10) {        Write-Host "  → Likely cause: STANDBY LIST PRESSURE." -ForegroundColor Red        Write-Host "    Fix:" -ForegroundColor Green        Write-Host "      - Keep EmptyStandbyList.exe in the launcher folder (already used automatically)." -ForegroundColor Green        Write-Host "      - Avoid long multi-hour sessions without restarting the game." -ForegroundColor Green    }    else {        Write-Host "  → Memory did not appear critically exhausted at last sample." -ForegroundColor Yellow        Write-Host "    Possible causes: GPU driver, specific mod, or engine bug unrelated to RAM." -ForegroundColor Yellow    }    "=== MEMORY GUARDIAN – ANALYSIS COMPLETE ===" | Out-File $log -Append}# -------------------------------# 1. Ensure required folders exist# -------------------------------$sfRoot = "C:\Users\latsh\Documents\My Games\Starfield"$folders = @(    $sfRoot,    "$sfRoot\Creations",    "$sfRoot\Saves")foreach ($f in $folders) {    if (!(Test-Path $f)) {        Write-Host "Creating missing folder: $f" -ForegroundColor Yellow        New-Item -ItemType Directory -Path $f | Out-Null        "Created folder: $f" | Out-File $log -Append    }}# -------------------------------# 2. Fix permissions# -------------------------------Write-Host "Fixing folder permissions..." -ForegroundColor Yellowicacls $sfRoot /grant latsh:(OI)(CI)F /T | Out-Null"Permissions repaired." | Out-File $log -Append# -------------------------------# 3. Remove OneDrive-style read-only flags# -------------------------------Write-Host "Clearing read-only attributes..." -ForegroundColor Yellowattrib -R "$sfRoot" /S /D"Attributes cleared." | Out-File $log -Append# -------------------------------# 4. Auto-backup INIs# -------------------------------$backupDir = "$sfRoot\INI_Backups"if (!(Test-Path $backupDir)) { New-Item -ItemType Directory -Path $backupDir | Out-Null }$timestamp = Get-Date -Format "yyyy-MM-dd_HH-mm-ss"Copy-Item "$sfRoot\*.ini" "$backupDir\INI_Backup_$timestamp" -ErrorAction SilentlyContinue"INI backup created: INI_Backup_$timestamp" | Out-File $log -Append# -------------------------------# 5. GPU Scheduling Registry Fix# -------------------------------Write-Host "Applying GPU Scheduling fix..." -ForegroundColor Yellowreg add "HKLM\SYSTEM\CurrentControlSet\Control\GraphicsDrivers" /v HwSchMode /t REG_DWORD /d 2 /f | Out-Null"GPU Scheduling enabled." | Out-File $log -Append# -------------------------------# 6. Shader Cache Purge# -------------------------------Write-Host "Purging shader caches..." -ForegroundColor Yellow$dxCache = "$env:LOCALAPPDATA\D3DSCache"$nvCache = "$env:LOCALAPPDATA\NVIDIA\DXCache"$amdCache = "$env:LOCALAPPDATA\AMD\DxCache"$shaderCaches = @($dxCache, $nvCache, $amdCache)foreach ($cache in $shaderCaches) {    if (Test-Path $cache) {        Remove-Item "$cache\*" -Force -Recurse -ErrorAction SilentlyContinue        "Purged shader cache: $cache" | Out-File $log -Append    }}# -------------------------------# 7. DirectX Pipeline Flush# -------------------------------Write-Host "Flushing DirectX pipeline..." -ForegroundColor YellowRemove-Item "$env:LOCALAPPDATA\Starfield\Pipeline.cache" -ErrorAction SilentlyContinue"Pipeline.cache removed." | Out-File $log -Append# -------------------------------# 8. Steam Integrity Auto-Check# -------------------------------Write-Host "Running Steam integrity check..." -ForegroundColor Yellow"Running Steam integrity check..." | Out-File $log -AppendStart-Process "steam://validate/1716740"Start-Sleep -Seconds 5# -------------------------------# 9. Flush RAM + Standby List (pre-launch)# -------------------------------Write-Host "Pre-launch RAM cleanup..." -ForegroundColor YellowClear-Content "$env:TEMP\*" -ErrorAction SilentlyContinueStart-Sleep -Milliseconds 500Invoke-StandbyFlushInvoke-JunkKill# -------------------------------# 10. Ultimate Performance Mode# -------------------------------Write-Host "Setting Ultimate Performance..." -ForegroundColor Yellowpowercfg -setactive e9a42b02-d5df-448d-aa00-03f14749eb61"Ultimate Performance enabled." | Out-File $log -Append# -------------------------------# 11. Launch Starfield.exe# -------------------------------$starfieldPath = "C:\SteamLibrary\steamapps\common\Starfield\Starfield.exe"if (!(Test-Path $starfieldPath)) {    Write-Host "ERROR: Starfield.exe not found!" -ForegroundColor Red    "ERROR: Starfield.exe missing." | Out-File $log -Append    exit}Write-Host "Launching Starfield.exe with -sfc_disable_creations..." -ForegroundColor Cyan"Launching Starfield.exe with -sfc_disable_creations..." | Out-File $log -Append$proc = Start-Process $starfieldPath -ArgumentList "-sfc_disable_creations" -PassThruStart-Sleep -Seconds 3# -------------------------------# 12. Set High Priority# -------------------------------try {    $proc.PriorityClass = "High"    Write-Host "Priority set to HIGH." -ForegroundColor Green    "Priority set to HIGH." | Out-File $log -Append}catch {    Write-Host "Could not set priority." -ForegroundColor Red    "Priority set FAILED." | Out-File $log -Append}# -------------------------------# 13. Start Memory Guardian (Active Protector)# -------------------------------Start-MemoryGuardian -StarfieldProc $proc# -------------------------------# 14. Monitor for pre-menu CTD / Crash# -------------------------------Write-Host "Monitoring for early crash..." -ForegroundColor YellowStart-Sleep -Seconds 10if ($proc.HasExited) {    Write-Host "`nStarfield quit early. Attempting fallback..." -ForegroundColor Red    "Detected early CTD." | Out-File $log -Append    Analyze-MemoryCrash    Remove-Item "$sfRoot\Starfield.ini" -ErrorAction SilentlyContinue    Remove-Item "$sfRoot\StarfieldPrefs.ini" -ErrorAction SilentlyContinue    Remove-Item "$sfRoot\ContentCatalog.txt" -ErrorAction SilentlyContinue    "INI + metadata reset." | Out-File $log -Append    Write-Host "Retrying launch..." -ForegroundColor Cyan    Start-Process $starfieldPath -Priority High -ArgumentList "-sfc_disable_creations"}else {    Write-Host "`nStarfield appears stable. Enjoy!" -ForegroundColor Green    "Launch stable." | Out-File $log -Append}"=== TURBO LAUNCH + MEMORY GUARDIAN COMPLETE ===`n" | Out-File $log -Append